            b[i+4] = vtmp_b[4]; b[i+5] = vtmp_b[5]; b[i+6] = vtmp_b[6]; b[i+7] = vtmp_b[7];

            vsum += vtmp_a;
        }

        sum += vsum[0] + vsum[1] + vsum[2] + vsum[3] +
